Next, the cpp. Parse: iterate over the characters. Allowed characters: digits, '+', '-', '.', ' ', '(', ')'. If there's a '+', it must be the first non-whitespace character... actually, the tests only have "+1 (223) 456-7890". More simply: strip out everything that isn't a digit or '+'. If there's a '+', it must be at the beginning (before any digit) and must be followed by '1'. Collect the digits. Then validate the length.

Implementation:

```cpp
#include "phone_number.h"
#include <cctype>

namespace phone_number {

phone_number::phone_number(const std::string& raw) {
    for (char c : raw) {
        if (std::isdigit(static_cast<unsigned char>(c))) {
            digits_.push_back(c);
        } else if (c == '+') {
            if (!digits_.empty()) {
                throw std::domain_error("invalid phone number");
            }
        } else if (c == '-' || c == '.' || c == ' ' || c == '(' || c == ')') {
            // punctuation, ignore
        } else {
            throw std::domain_error("invalid phone number");
        }
    }
    if (digits_.size() == 11) {
        if (digits_.front() != '1') {
            throw std::domain_error("invalid phone number");
        }
        digits_ = digits_.substr(1);
    } else if (digits_.size() != 10) {
        throw std::domain_error("invalid phone number");
    }
    if (digits_[0] < '2' || digits_[3] < '2') {
        throw std::domain_error("invalid phone number");
    }
}

std::string phone_number::number() const {
    return digits_;
}

}  // namespace phone_number
